// Shared types only. No logic in this file.

// ---------------------------------------------------------------------------
// App
// ---------------------------------------------------------------------------

/**
 * Hono generic for every app and router: gives routes a typed `c.env.DB`.
 * `Env` is generated by `wrangler types` (api/worker-configuration.d.ts).
 */
export type AppEnv = {
  Bindings: Env
}

// ---------------------------------------------------------------------------
// Database rows: snake_case, exactly as SQLite returns them.
// Each type lists only the columns our queries SELECT, not the whole table.
// ---------------------------------------------------------------------------

/** Any query that selects just `id` (existence checks, member lists). */
export type IdRow = {
  id: string
}

/** A share as returned by the pay UPDATE ... RETURNING. */
export type ShareRow = {
  id: string
  member_id: string
  amount_cents: number
  paid_at: string | null
}

/** A share plus the key that paid it (used to tell a retry from a conflict). */
export type PaidShareRow = ShareRow & {
  idempotency_key: string | null
}

/** One bill in the list-bills query. */
export type BillRow = {
  id: string
  title: string
  total_cents: number
}

/** A share in the list-bills query: which bill it belongs to, plus the member's name. */
export type BillShareRow = ShareRow & {
  bill_id: string
  member_name: string
}

/** One row of the balances query: a member and their unpaid total. */
export type BalanceRow = {
  member_id: string
  name: string
  outstanding_cents: number
}

// ---------------------------------------------------------------------------
// API responses: camelCase, exactly what clients receive
// ---------------------------------------------------------------------------

/** POST /api/homes */
export type HomeResponse = {
  id: string
  name: string
}

/** POST /api/homes/:homeId/members */
export type MemberResponse = {
  id: string
  homeId: string
  name: string
}

/** One share inside a bill, and POST /api/bills/:billId/shares/:shareId/pay */
export type ShareResponse = {
  id: string
  memberId: string
  amountCents: number
  paidAt: string | null
}

/** POST /api/homes/:homeId/bills */
export type BillResponse = {
  id: string
  homeId: string
  title: string
  totalCents: number
  shares: ShareResponse[]
}

/** A share in the bills list: a normal share plus the member's name for display. */
export type BillShareResponse = ShareResponse & {
  memberName: string
}

/** One bill in the bills list, with its shares in member order. */
export type BillWithSharesResponse = {
  id: string
  homeId: string
  title: string
  totalCents: number
  shares: BillShareResponse[]
}

/** GET /api/homes/:homeId/bills */
export type BillsResponse = {
  bills: BillWithSharesResponse[]
}

/** One member's line in the balances list. */
export type BalanceResponse = {
  memberId: string
  name: string
  outstandingCents: number
}

/** GET /api/homes/:homeId/balances */
export type BalancesResponse = {
  balances: BalanceResponse[]
}
